mapper.select:
SELECT CLCBA.bill_BANK_ACCOUNT_ID, CLCBA.BANK_ACCOUNT_ID, CLCBA.bill_id, CLCBA.CONTRACT_ID, CLCBA.BANK_ACCOUNT_TYPE, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code = 'LON.ACCOUNT_TYPE' and scb.code_id = scvb.code_id and scvb.value = CLCBA.BANK_ACCOUNT_TYPE) as BANK_ACCOUNT_TYPE_N, CLCBA.DESCRIPTION, CLCBA.ENABLED_FLAG, CLCBA.LON_BANK_ACCOUNT_ID, CLCBA.ACCOUNT_SOURCE, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code = 'LON_CON_ACCOUNT_SOURCE' and scb.code_id = scvb.code_id and scvb.value = CLCBA.ACCOUNT_SOURCE) as ACCOUNT_SOURCE_N, CLBA.BANK_ACCOUNT_NAME AS BANK_ACCOUNT_ID_N, CLBA.BANK_BRANCH_NAME AS BANK_BRANCH_NAME, CLBA.BANK_ACCOUNT_NAME AS BANK_ACCOUNT_NAME, CLBA.BANK_ACCOUNT_NAME AS BANK_ACCOUNT_NAME_N, CLBA.BANK_ACCOUNT_NUM AS BANK_ACCOUNT_NUM, CLCBA.OBJECT_VERSION_NUMBER FROM jc_bill_bank_account CLCBA LEFT JOIN CSH_BANK_ACCOUNT CBA ON CBA.BANK_ACCOUNT_ID=CLCBA.BANK_ACCOUNT_ID LEFT JOIN CSH_BANK CB ON CB.BANK_ID=CBA.BANK_ID LEFT JOIN CT_LON_BANK_ACCOUNT CLBA ON CLBA.BANK_ACCOUNT_ID=CLCBA.BANK_ACCOUNT_ID WHERE 1=1
AND CLCBA.bill_id=#{billId}
and CLCBA.bill_bank_account_id = #{billBankAccountId}
